style.css:
/* ========================================================
 * x.com (Twitter) 画像横スクロール解除・全枚数一覧表示
 * 
 * NOTE: このコードはGeminiを徹底的にしばき倒し、
 * 数多の表示崩れと屍を乗り越えて作成されました。
 * ======================================================== */

/* x.com 画像カルーセルの横スクロール解除・全枚数一覧表示 */
div[data-testid="ScrollSnap-List"] {
  flex-wrap: wrap !important;
  overflow: visible !important;
  margin: 0 !important;
  padding: 0 !important;
  scroll-padding: 0 !important;
  height: auto !important;
}

/* 各画像カードの配置調整 */
div[data-testid="ScrollSnap-List"] > div[role="presentation"] {
  flex-shrink: 0 !important;
  margin-right: 4px !important;
  margin-bottom: 8px !important;
}

/* 横スクロール用の左右矢印ボタンを非表示 */
div[data-testid="ScrollSnap-prevButtonWrapper"],
div[data-testid="ScrollSnap-nextButtonWrapper"] {
  display: none !important;
}
